    /// Reconcile a `GtkGrid`'s children at their row-major cell positions.
    fn sync_grid_children(&mut self, parent_id: u32, children: &[u32], node: &HostNode) {
        let Some(parent) = self.widgets.get(&parent_id).cloned() else {
            return;
        };
