/// The current child widgets of a native widget, in draw/child order.
fn child_widgets(widget: &gtk::Widget) -> Vec<gtk::Widget> {
    let mut out = Vec::new();
    let mut c = widget.first_child();
    while let Some(w) = c {
        out.push(w.clone());
        c = w.next_sibling();
    }
    out
}

/// Whether a grid's children already sit at their target cell positions.
fn grid_matches(
    grid: &gtk::Grid,
    children: &[u32],
    columns: Option<u32>,
    widgets: &HashMap<u32, gtk::Widget>,
) -> bool {
    if child_widgets(grid).len() != children.len() {
        return false;
    }
    for (idx, child_id) in children.iter().enumerate() {
        let Some(w) = widgets.get(child_id) else { return false };
        let (row, col) = layout::grid_cell_position(idx as u32, columns);
        if grid.child_at(col as i32, row as i32).as_ref() != Some(w) {
            return false;
        }
    }
    true
}
